

from pathlib import Path

import matplotlib
matplotlib.use("Agg")

import matplotlib.pyplot as plt
import pandas as pd
import yaml


# --------------------------------------------------
# 0. CONFIGURATION AND DATA LOADING
# --------------------------------------------------

ROOT = Path(__file__).resolve().parent.parent

with open(ROOT / "config.yaml", "r") as f:
    config = yaml.safe_load(f)

OUT = ROOT / config["paths"]["outputs"]
DATA = OUT / "AirBnB_all_chch.csv"

OUT.mkdir(parents=True, exist_ok=True)

# Load Christchurch Airbnb data generated by the pipeline
df = pd.read_csv(DATA)

required_columns = [
    "year_month",
    "price",
    "number_of_reviews",
    "last_review",
    "neighbourhood",
]

missing_columns = [
    col for col in required_columns if col not in df.columns
]

if missing_columns:
    raise ValueError(
        f"Required columns missing: {missing_columns}"
    )

# Convert data types
df["year_month"] = pd.to_datetime(
    df["year_month"].astype(str),
    format="%Y-%m",
    errors="coerce"
)

# Handle prices formatted as strings, including $ and commas
df["price"] = pd.to_numeric(
    df["price"]
    .astype(str)
    .str.replace(r"[$,]", "", regex=True),
    errors="coerce"
)

df["number_of_reviews"] = pd.to_numeric(
    df["number_of_reviews"],
    errors="coerce"
)

df["last_review"] = pd.to_datetime(
    df["last_review"],
    errors="coerce"
)

if df["year_month"].notna().sum() == 0:
    raise ValueError("No valid year_month values found.")

# --------------------------------------------------
# 1. IDENTIFY AVAILABLE MONTHS
# --------------------------------------------------

monthly_summary = (
    df.dropna(subset=["year_month"])
    .groupby("year_month")
    .agg(
        total_listings=("year_month", "size"),
        valid_prices=("price", "count"),
        valid_reviews=("number_of_reviews", "count"),
        valid_review_dates=("last_review", "count")
    )
    .sort_index()
)

monthly_summary.index = monthly_summary.index.strftime("%Y-%m")

monthly_summary.to_csv(
    OUT / "leland_monthly_data_summary.csv"
)

print("\nAvailable Airbnb data by month:")
print(monthly_summary.to_string())

# Select latest month containing valid prices
valid_price_months = df.loc[
    df["price"].notna() & df["year_month"].notna(),
    "year_month"
]

if valid_price_months.empty:
    raise ValueError(
        "No valid price data found in any month."
    )

latest_month = valid_price_months.max()

latest = df.loc[
    df["year_month"] == latest_month
].copy()

month_label = latest_month.strftime("%B %Y")

print(f"\nLatest month with valid prices: {month_label}")

# --------------------------------------------------
# 2. SUMMARY STATISTICS
# --------------------------------------------------

df.describe(include="all").to_csv(
    OUT / "leland_summary_statistics.csv"
)

df.corr(numeric_only=True).to_csv(
    OUT / "leland_correlations.csv"
)

missingness = pd.DataFrame({
    "missing_count": df.isna().sum(),
    "missing_percentage": df.isna().mean() * 100
})

missingness.to_csv(
    OUT / "leland_missingness.csv"
)

missing_corr = df.isna().astype(int).corr()

missing_corr = missing_corr.dropna(
    axis=0, how="all"
)

missing_corr = missing_corr.dropna(
    axis=1, how="all"
)

missing_corr.to_csv(
    OUT / "leland_missingness_correlations.csv"
)

# --------------------------------------------------
# 3. BOXPLOTS FOR NUMERIC COLUMNS
# --------------------------------------------------

exclude = {
    "id",
    "host_id",
    "latitude",
    "longitude",
    "license"
}

numeric_cols = [
    col
    for col in df.select_dtypes(include="number").columns
    if col not in exclude
]

for col in numeric_cols:

    values = df[col].dropna()

    if values.empty:
        print(f"Skipping boxplot for {col}: no valid data.")
        continue

    fig, ax = plt.subplots(figsize=(8, 4))

    ax.boxplot(values)

    ax.set_title(f"Boxplot of {col}")
    ax.set_ylabel(col)

    fig.savefig(
        OUT / f"leland_boxplot_{col}.png",
        dpi=200,
        bbox_inches="tight"
    )

    plt.close(fig)

# --------------------------------------------------
# 4. PRICE HISTOGRAMS
# --------------------------------------------------

for data, filename, title in [
    (
        df,
        "leland_price_all.png",
        "All available months"
    ),
    (
        latest,
        "leland_price_latest.png",
        month_label
    ),
]:

    values = data["price"].dropna()

    if values.empty:
        print(f"Skipping price histogram for {title}.")
        continue

    fig, ax = plt.subplots(figsize=(10, 6))

    ax.hist(
        values,
        bins=50,
        edgecolor="black"
    )

    ax.set_title(
        f"Christchurch Airbnb prices — {title}"
    )

    ax.set_xlabel("Price")
    ax.set_ylabel("Number of listings")

    fig.savefig(
        OUT / filename,
        dpi=200,
        bbox_inches="tight"
    )

    plt.close(fig)

# --------------------------------------------------
# 5. DAYS SINCE LAST REVIEW
# --------------------------------------------------

# Each month's latest observed review is the reference date
reference_dates = (
    df.groupby("year_month")["last_review"]
    .transform("max")
)

df["days_since_review"] = (
    reference_dates - df["last_review"]
).dt.days

# Select latest month containing valid review dates
valid_review_months = df.loc[
    df["days_since_review"].notna(),
    "year_month"
].dropna()

if not valid_review_months.empty:

    latest_review_month = valid_review_months.max()

    latest_reviews = df.loc[
        df["year_month"] == latest_review_month,
        "days_since_review"
    ].dropna()

    review_month_label = (
        latest_review_month.strftime("%B %Y")
    )

    fig, ax = plt.subplots(figsize=(10, 6))

    ax.hist(
        latest_reviews,
        bins=50,
        edgecolor="black"
    )

    ax.set_title(
        f"Days since last review — {review_month_label}"
    )

    ax.set_xlabel("Days since last review")
    ax.set_ylabel("Number of listings")

    fig.savefig(
        OUT / "leland_days_since_review.png",
        dpi=200,
        bbox_inches="tight"
    )

    plt.close(fig)

else:
    print("Skipping days since review: no valid dates.")
    (OUT / "leland_days_since_review.png").unlink(
        missing_ok=True
    )

# --------------------------------------------------
# 6. TOP 10% MOST REVIEWED LISTINGS
# --------------------------------------------------

# Select latest month with valid review counts
# and neighbourhood data
eligible = df.loc[
    df["year_month"].notna()
    & df["number_of_reviews"].notna()
    & df["neighbourhood"].notna()
].copy()

if not eligible.empty:

    latest_top_month = eligible["year_month"].max()

    top_month = eligible.loc[
        eligible["year_month"] == latest_top_month
    ].copy()

    reviews = top_month["number_of_reviews"]

    cutoff = reviews.quantile(0.90)

    top = top_month.loc[
        top_month["number_of_reviews"] >= cutoff
    ]

    counts = top["neighbourhood"].value_counts()

    top_month_label = (
        latest_top_month.strftime("%B %Y")
    )

    if not counts.empty:

        fig, ax = plt.subplots(figsize=(10, 6))

        counts.sort_values().plot(
            kind="barh",
            ax=ax
        )

        ax.set_title(
            "Top 10% most reviewed listings "
            f"by neighbourhood — {top_month_label}"
        )

        ax.set_xlabel("Number of listings")
        ax.set_ylabel("Neighbourhood")

        fig.savefig(
            OUT / "leland_top10_reviews.png",
            dpi=200,
            bbox_inches="tight"
        )

        plt.close(fig)

    else:
        print("Skipping top-reviewed plot: no neighbourhoods.")
        (OUT / "leland_top10_reviews.png").unlink(
            missing_ok=True
        )

else:
    print("Skipping top-reviewed plot: no valid review data.")
    (OUT / "leland_top10_reviews.png").unlink(
        missing_ok=True
    )

# --------------------------------------------------
# 7. COMPLETION MARKER FOR MAKE
# --------------------------------------------------

(OUT / "leland_reports.done").write_text(
    f"Reports generated for {month_label}\n"
)


